import{_ as u}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/EN.P9aPnFBv.js";import{_ as v,a as h,b as r,c as g,d as b,e as f,f as x,g as y,h as q,i as A,j as z}from"./chunks/M-SNOj.BjML9gyj.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as s}from"./chunks/OFF.BrU7kQE-.js";import{_ as t}from"./chunks/ON.DXVlsWbj.js";import{_ as n}from"./chunks/BDM.scaBLLhv.js";import{_,C as S,o as k,c as D,a3 as o,j as l,a as p,E as c,w as m}from"./chunks/framework.g9mfNVRQ.js";const $=JSON.parse('{"title":"Alarmes et alertes","description":"","frontmatter":{"source_hash":"2ef67c25aa","source_commit":"8f65827","i18n_outdated":true},"headers":[],"relativePath":"fr/use/alarms.md","filePath":"fr/use/alarms.md"}'),P={name:"fr/use/alarms.md"},L={class:"admonition xdrip"},E={style:{"background-color":"dimgray",color:"white","text-align":"center"}};function R(N,i,T,C,V,w){const d=S("big");return k(),D("div",null,[i[3]||(i[3]=o('<div class="admonition xdrip"><p class="admonition-title"><img src="'+u+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_add_alert_grey600_48dp.png" style="width:5%;"> Alarmes et alertes</p></div><p>xDrip permet de configurer de nombreuses alertes.</p><p>Si xDrip est votre seule application de suivi de la glycémie, il est recommandé d&#39;activer au moins trois alertes :</p><ul><li>Alerte Basse</li><li>Alerte Haute</li><li>Alerte de lecture manquée</li></ul><h3 id="glucose-level-alerts-list" tabindex="-1">Liste des alertes de niveau de glycémie <a class="header-anchor" href="#glucose-level-alerts-list" aria-label="Permalink to &quot;Liste des alertes de niveau de glycémie {#glucose-level-alerts-list}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Liste des alertes de niveau de glycémie</p></div><p>Par défaut, une alerte Basse et une alerte Haute sont définies.</p><p>Les alertes Basses se déclenchent lorsque la glycémie est inférieure ou égale à la valeur de l&#39;alerte, les alertes Hautes lorsqu&#39;elle est supérieure ou égale.</p><p>Pour créer une nouvelle alerte, appuyez sur la barre de titre <code>CRÉER ALERTE BASSE</code> ou <code>CRÉER ALERTE HAUTE</code>.</p><p>Pour modifier une alerte existante, faites un appui long sur l&#39;alerte</p><div class="admonition xdrip"><p class="admonition-title">☰ Liste d&#39;alertes</p><div style="background-color:gray;color:white;text-align:center;">  CRÉER ALERTE BASSE </div><p><small>  Alerte Basse       70      toute la journée</small><br><small>Ignorer le mode silencieux   Sonnerie par défaut (sonnerie inconnue)</small></p><div style="background-color:gray;color:white;text-align:center;">  CRÉER ALERTE HAUTE </div><small>  Alerte Haute       224      toute la journée</small><small>Ignorer le mode silencieux   Sonnerie par défaut (sonnerie inconnue)</small></div><ol><li>Vous pouvez donner à une alerte le nom de votre choix, tant qu&#39;aucune autre alerte ne porte le même nom</li><li>Le seuil est la glycémie qui déclenche l&#39;alarme ; une seule alarme peut utiliser cette valeur</li><li>La mise en veille par défaut est la durée proposée lorsque vous mettez l&#39;alerte en veille</li><li>L&#39;alarme se déclenche de nouveau toutes les x minutes si elle n&#39;est pas confirmée</li></ol><div class="admonition xdrip"><p class="admonition-title">☰ Modifier l&#39;alerte</p><p>   Modification Alerte Basse</p><p>  <small>Nom de l&#39;alerte: <u>Alerte Basse</u></small> <span style="background-color:green;color:white;text-align:center;">1</span><br>   <small>Seuil: <u>70</u></small> <span style="background-color:green;color:white;text-align:center;">2</span><br>   <small>Mise en veille par défaut: <u>35</u></small> <span style="background-color:green;color:white;text-align:center;">3</span><br>   <small>Rappeler toutes les x minutes: <u>1</u></small> <span style="background-color:green;color:white;text-align:center;">4</span><br>   <small>si non confirmé</small></p><p>  <small>Son d&#39;alerte: <u>Sonnerie par défaut (sonnerie inconnue)</u></small> <span style="background-color:green;color:white;text-align:center;">5</span></p></div><p> 5. Vous pouvez personnaliser le son de l&#39;alerte : appuyez sur CHOISIR LE FICHIER pour sélectionner la sonnerie de cette alarme.</p><ul><li><p>Son/Alarme Système vous permet de choisir parmi les sonneries de votre téléphone.</p></li><li><p>Son/Alarme personnalisés vous permet de choisir votre propre son ou musique.</p></li><li><p>Son xDrip par défaut utilise le son par défaut de l&#39;application.</p></li></ul><div class="admonition xdripitem"><p class="admonition-title">Quel type de son ?</p><p> Son/Alarme Système<br>  Son/Alarme personnalisés<br>  Son xDrip par défaut</p></div><p>Par défaut, l&#39;alarme est active toute la journée.</p><div class="admonition xdripitem"><p class="admonition-title"><small>Sélectionner la période de l&#39;alerte</small></p><p>         ✅ toute la journée</p></div><p>Si vous décochez la case, vous pouvez définir les heures d&#39;activité.<br> Appuyez sur l&#39;heure de début et l&#39;heure de fin pour définir la plage horaire pendant laquelle l&#39;alarme est active.</p><div class="admonition xdripitem"><p class="admonition-title"><small>Sélectionner la période de l&#39;alerte</small></p><p>         ☐ toute la journée<br>         0:00 - 0:00</p></div><p>Vous pouvez désactiver l&#39;alarme (décocher) lorsque le téléphone est en mode silencieux (désactivation déconseillée)</p><div class="admonition xdripitem"><p class="admonition-title"><small>Remplacer le mode silencieux du téléphone</small><span class="symbol"><small>✅</small></span></p></div><p>Forcer par haut-parleur fait sonner l&#39;alarme sur le téléphone même si vous utilisez d&#39;autres haut-parleurs (Bluetooth par exemple)</p><div class="admonition xdripitem"><p class="admonition-title"><small>Forcer par haut-parleur</small><span class="symbol"><small>✅</small></span></p></div><p>Vibrer en cas d&#39;alerte active le vibreur du téléphone</p><div class="admonition xdripitem"><p class="admonition-title"><small>Vibrer en cas d&#39;alerte</small><span class="symbol"><small>✅</small></span></p></div><p>Désactiver l&#39;alerte la désactive complètement : elle apparaît barrée dans la Liste d&#39;alertes</p><div class="admonition xdripitem"><p class="admonition-title"><small>Désactiver l&#39;alerte</small><span class="symbol"><small>☐</small></span></p></div><p><span style="background-color:gray;color:white;"> ALERTE DE TEST </span> fait sonner cette alerte</p><p><span style="background-color:gray;color:white;"> SAUVER L&#39;ALERTE </span> enregistre cette alerte nouvelle ou modifiée</p><p><span style="background-color:gray;color:white;"> SUPPRIMER L&#39;ALERTE </span> supprime cette alerte</p><p><span style="background-color:gray;color:white;"> ARRÊTER L&#39;ALERTE AVANT QU&#39;ELLE NE DÉCLENCHE </span> vous permet d&#39;empêcher l&#39;alerte de se déclencher : par exemple, si vous avez déjà traité une hypo ou une hyper prévue et savez que la glycémie va évoluer de toute façon, vous pouvez éviter d&#39;entendre l&#39;alarme pendant la durée de votre choix.</p><h3 id="glucose-alerts-settings" tabindex="-1">Paramètres d&#39;alertes glycémiques <a class="header-anchor" href="#glucose-alerts-settings" aria-label="Permalink to &quot;Paramètres d&#39;alertes glycémiques {#glucose-alerts-settings}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Paramètres d&#39;alertes glycémiques</p></div><h5 id="alert-volume-profile" tabindex="-1">Profil de volume d&#39;alerte <a class="header-anchor" href="#alert-volume-profile" aria-label="Permalink to &quot;Profil de volume d&#39;alerte {#alert-volume-profile}&quot;">​</a></h5><p>Vous pouvez personnaliser le volume de vos alertes</p><div class="admonition xdripitem"><p class="admonition-title">Profil de volume d&#39;alerte</p><p> Haute <span style="float:right;">○ </span>   <br>  Moyenne <span style="float:right;">○ </span>   <br>  Montante <span style="float:right;">● </span>   <br>  Vibreur uniquement <span style="float:right;">○ </span>   <br>  Silencieux <span style="float:right;">○ </span>   </p></div><p>Le volume Montante est recommandé si vous ne voulez pas que l&#39;alarme retentisse immédiatement à plein volume (utile la nuit). Vous pouvez aussi <a href="#delay-ascending-volume">retarder</a> le volume ascendant pour filtrer les valeurs bruitées, et limiter le volume maximum.</p><p>Depuis le <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.10.16" target="_blank" rel="noreferrer">16 oct. 2026</a>, choisir Vibreur uniquement ou Silencieux demande une confirmation : avec ces profils, les alertes ne font aucun son, même celles pour lesquelles Ignorer le mode silencieux est activé. Le profil n&#39;est modifié que si vous confirmez.</p><h5 id="audio-focus" tabindex="-1">Priorité audio <a class="header-anchor" href="#audio-focus" aria-label="Permalink to &quot;Priorité audio {#audio-focus}&quot;">​</a></h5><p>La priorité audio vous permet de décider comment gérer les autres sons lorsqu&#39;une alarme ou une alerte xDrip se déclenche.</p><div class="admonition xdripitem"><p class="admonition-title">Priorité audio</p><p>Choisir ce qu&#39;il faut faire avec les autres applications lors de lecture d&#39;alertes et réglage du volume du système</p></div><p>Vous pouvez baisser automatiquement le volume, mettre en pause les autres applications qui jouent des sons (comme les lecteurs multimédias) ou mettre en pause tous les autres sons pour mieux entendre le son de xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Priorité audio</p><p> Ne pas ajuster les sons des autres applications <span style="float:right;">● </span>   <br>  Réduire le volume des autres applications <span style="float:right;">○ </span>   <br>  Mettre en pause les autres applications en cours de lecture audio <span style="float:right;">○ </span>   <br>  Mettre en pause tous les autres sons <span style="float:right;">○ </span>   </p></div><h5 id="smart-snoozing" tabindex="-1">Mise en veille intelligente <a class="header-anchor" href="#smart-snoozing" aria-label="Permalink to &quot;Mise en veille intelligente {#smart-snoozing}&quot;">​</a></h5><h5 id="smart-alerting" tabindex="-1">Alertes intelligentes <a class="header-anchor" href="#smart-alerting" aria-label="Permalink to &quot;Alertes intelligentes {#smart-alerting}&quot;">​</a></h5><p>La mise en veille intelligente et les alertes intelligentes évitent que l&#39;alerte se déclenche ou se relance si la glycémie évolue dans la bonne direction (vers le haut pour les alertes Basses, vers le bas pour les alertes Hautes). Les seuils pour considérer une évolution suffisante dans la bonne direction sont :</p><ul><li>Variation supérieure à +4 mg/dl en 5 minutes pour une alerte Basse</li><li>Variation supérieure à -1 mg/dl en 5 minutes pour une alerte Haute</li></ul><div class="admonition xdripitem"><p class="admonition-title">Mise en veille intelligente <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Rester inactif si la glycémie évolue dans la bonne direction</p></div><div class="admonition xdripitem"><p class="admonition-title">Alertes intelligentes <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Ne pas alerter si la glycémie évolue dans la bonne direction</p></div><h5 id="dont-alarm-during-phone-calls" tabindex="-1">Ne pas alerter pendant les appels téléphoniques <a class="header-anchor" href="#dont-alarm-during-phone-calls" aria-label="Permalink to &quot;Ne pas alerter pendant les appels téléphoniques {#dont-alarm-during-phone-calls}&quot;">​</a></h5><p>Les alarmes ne sonnent pas si elles se déclenchent pendant un appel téléphonique.</p><div class="admonition xdripitem"><p class="admonition-title">Ne pas alerter pendant les appels téléphoniques <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Alarmes silencieuses pendant les appels téléphoniques</p></div><h5 id="buttons-silence-alarms" tabindex="-1">La pression des boutons met en veille les alarmes <a class="header-anchor" href="#buttons-silence-alarms" aria-label="Permalink to &quot;La pression des boutons met en veille les alarmes {#buttons-silence-alarms}&quot;">​</a></h5><p>Cette option permet de mettre rapidement une alarme en veille en appuyant simplement sur le bouton de volume haut ou bas.</p><div class="admonition xdripitem"><p class="admonition-title">La pression des boutons met en veille les alarmes <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Appuyer sur le volume up ou down mettra en veille une alarme active lorsque l&#39;application est lancée</p></div><h5 id="alert-buttons" tabindex="-1">Boutons d&#39;alerte <a class="header-anchor" href="#alert-buttons" aria-label="Permalink to &quot;Boutons d&#39;alerte {#alert-buttons}&quot;">​</a></h5><p>Boutons d&#39;alerte ajoute un bouton d&#39;action dans la notification déroulante de l&#39;alerte.</p><div class="admonition xdripitem"><p class="admonition-title">Boutons d&#39;alerte <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Afficher les boutons d&#39;action (comme Snooze) dans les notifications d&#39;alerte</p></div><img src="'+v+'" style="zoom:75%;"><img src="'+h+'" style="zoom:75%;"><h5 id="start-snoozed" tabindex="-1">Démarrer silencieusement <a class="header-anchor" href="#start-snoozed" aria-label="Permalink to &quot;Démarrer silencieusement {#start-snoozed}&quot;">​</a></h5><p>Démarrer silencieusement applique le délai de mise en veille avant de déclencher l&#39;alarme. Vérifiez que la <code>Mise en veille par défaut</code> de l&#39;alarme est adaptée.</p><div class="admonition xdripitem"><p class="admonition-title">Démarrer silencieusement <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Les alertes commencent silencieuses et doivent persister pendant un certain temps pour se déclencher</p></div><h5 id="wake-screen" tabindex="-1">Allumer l&#39;écran <a class="header-anchor" href="#wake-screen" aria-label="Permalink to &quot;Allumer l&#39;écran {#wake-screen}&quot;">​</a></h5><p>Allume l&#39;écran pendant les alertes.</p><div class="admonition xdripitem"><p class="admonition-title">Allumer l&#39;écran<img src="'+s+'" style="zoom:75%;"></p><p> Allumer l&#39;écran pendant les alertes. Peut déverrouiller les appareils qui n&#39;ont pas de verrouillage d&#39;écran activé.</p></div><h5 id="use-camera-light" tabindex="-1">Utiliser la lumière de la caméra <a class="header-anchor" href="#use-camera-light" aria-label="Permalink to &quot;Utiliser la lumière de la caméra {#use-camera-light}&quot;">​</a></h5><p>Fait clignoter le flash de l&#39;appareil photo arrière pendant les alertes (lorsque le téléphone est en charge).</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser la lumière de la caméra<img src="'+s+'" style="zoom:75%;"></p><p> Allumer la lumière de la caméra lors des alertes si connecté à un chargeur</p></div><h5 id="shortcut-to-bg-level-alerts" tabindex="-1">Raccourci vers les alertes de niveau de glycémies <a class="header-anchor" href="#shortcut-to-bg-level-alerts" aria-label="Permalink to &quot;Raccourci vers les alertes de niveau de glycémies {#shortcut-to-bg-level-alerts}&quot;">​</a></h5><p>Vous pouvez ajouter un raccourci vers <code>Alertes de niveau</code> dans le menu principal de xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Raccourci vers les alertes de niveau de glycémies<img src="'+e+'" style="zoom:75%;"></p><p> Créer un raccourci sur la navigation principale vers l&#39;écran de niveau de glycémies</p></div><h5 id="suppress-alerts-if-missed-readings" tabindex="-1">Suppression des alertes en cas de lectures manquées <a class="header-anchor" href="#suppress-alerts-if-missed-readings" aria-label="Permalink to &quot;Suppression des alertes en cas de lectures manquées {#suppress-alerts-if-missed-readings}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Suppression des alertes en cas de lectures manquées</p></div><p>Les alertes de niveau restent actives même en l&#39;absence de signal (changement de capteur par exemple, ou abonné sans réseau). Cette option permet de les supprimer. Si vous l&#39;utilisez, vérifiez qu&#39;une alerte de lecture manquée est activée.</p><div class="admonition xdripitem"><p class="admonition-title">Suppression des alertes en cas de lectures manquées <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Supprime les alertes de mise en veille et actives après la période prédéfinie de lectures manquées</p></div><p>Vous pouvez définir le nombre de minutes au bout duquel les alertes doivent s&#39;arrêter.</p><div class="admonition xdripitem"><p class="admonition-title">Supprimer les alertes de mise en veille et actives après .. minutes (minimum 10)</p><p> Supprime les alertes de mise en veille et actives après la période prédéfinie de lectures manquées</p></div><h5 id="notification-channels" tabindex="-1">Canaux de Notification <a class="header-anchor" href="#notification-channels" aria-label="Permalink to &quot;Canaux de Notification {#notification-channels}&quot;">​</a></h5><p>Android 8.0 étant désormais la version minimale prise en charge, xDrip utilise toujours les canaux de notification Android pour vos alertes. Le paramètre qui les activait a été supprimé lors de l&#39;abandon d&#39;Android 7 (<a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.12" target="_blank" rel="noreferrer">12 juil. 2026</a>) : les canaux sont maintenant toujours actifs.</p><p>Depuis le <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9 sept. 2026</a>, xDrip ne crée plus que quatre canaux et joue lui-même le son et la vibration des alertes, au lieu de passer par le canal. Les anciens canaux sont supprimés automatiquement.</p><div class="admonition xdripitem"><p class="admonition-title">Canaux de notification xDrip</p><p> Alertes de niveau de glucose<br>  Autres alertes<br>  Général<br>  Notification en cours</p></div><p>Les réglages des canaux dans Paramètres Android / Notifications / Applications / xDrip décident seulement si la notification est affichée. Le son et la vibration dépendent des paramètres de xDrip : le <a href="#alert-volume-profile">profil de volume d&#39;alerte</a>, et les options Ignorer le mode silencieux et Vibrer en cas d&#39;alerte de chaque alerte. Désactiver un canal masque la notification mais ne rend pas l&#39;alerte silencieuse : désactivez plutôt l&#39;alerte dans xDrip.</p><h5 id="alert-priority" tabindex="-1">Priorité des alertes <a class="header-anchor" href="#alert-priority" aria-label="Permalink to &quot;Priorité des alertes {#alert-priority}&quot;">​</a></h5><p>Depuis le <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9 sept. 2026</a>, lorsque deux alertes se chevauchent, la plus importante l&#39;emporte : elle interrompt le son et la vibration d&#39;une alerte moins importante déjà en cours, et une alerte moins importante ne peut pas interrompre une alerte plus importante qui sonne encore. Cela ne concerne que le son et la vibration, pas la mise en veille ni la fermeture. De la priorité la plus haute à la plus basse :</p><ol><li>Lectures manquées</li><li>Niveau de glycémie bas</li><li>Haute persistante</li><li>Niveau de glycémie haut</li><li>Prévision d&#39;hypoglycémie</li><li>Glycémie en chute ou en augmentation rapide</li><li>Expiration du capteur</li><li>Alarme BlueReader</li><li>Alertes de valeurs incorrectes (bruit)</li><li>Rappels</li><li>Redémarrage de session OB1</li><li>Autres notifications</li></ol><p>Depuis le <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.10.09" target="_blank" rel="noreferrer">9 oct. 2026</a>, lorsque le téléphone est en mode silencieux (ou que le <a href="#alert-volume-profile">profil de volume d&#39;alerte</a> Silencieux est sélectionné) et qu&#39;Ignorer le mode silencieux est désactivé, les alertes jusqu&#39;à Glycémie en chute ou en augmentation rapide inscrivent quand même dans le journal qu&#39;aucun son n&#39;a été joué : vous pouvez ainsi voir après coup qu&#39;une alerte s&#39;est déclenchée.</p><h5 id="ascending-volume-settings" tabindex="-1">Réglages du volume croissant <a class="header-anchor" href="#ascending-volume-settings" aria-label="Permalink to &quot;Réglages du volume croissant {#ascending-volume-settings}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Réglages du volume croissant</p></div><h5 id="delay-ascending-volume" tabindex="-1">Délai du volume ascendant <a class="header-anchor" href="#delay-ascending-volume" aria-label="Permalink to &quot;Délai du volume ascendant {#delay-ascending-volume}&quot;">​</a></h5><p>Vous pouvez retarder le démarrage du son de l&#39;alerte à volume ascendant sans retarder la vibration, qui démarre dès le déclenchement de l&#39;alerte.</p><div class="admonition xdripitem"><p class="admonition-title">Délai du volume ascendant<img src="'+a+'" style="zoom:75%;"></p><p> Pour le profil de volume ascendant, retarder le démarrage du son d&#39;alerte de 3 minutes. Le vibreur (si activé) démarre dès que l&#39;alerte se déclenche, quel que soit ce paramètre.</p></div><h5 id="ascend-to-medium" tabindex="-1">Augmentation vers le milieu <a class="header-anchor" href="#ascend-to-medium" aria-label="Permalink to &quot;Augmentation vers le milieu {#ascend-to-medium}&quot;">​</a></h5><p>Vous pouvez limiter le volume maximum des alertes et alarmes à volume ascendant au volume moyen au lieu du maximum.</p><div class="admonition xdripitem"><p class="admonition-title">Augmentation vers le milieu<img src="'+e+'" style="zoom:75%;"></p><p> Lorsqu&#39;il est activé, le profil de volume ascendant augmentera vers le volume moyen au lieu du maximum</p></div><h3 id="calibration-alerts" tabindex="-1">Alertes de calibration <a class="header-anchor" href="#calibration-alerts" aria-label="Permalink to &quot;Alertes de calibration {#calibration-alerts}&quot;">​</a></h3><p>Si votre capteur nécessite un étalonnage régulier, vous pouvez configurer xDrip pour qu&#39;il vous avertisse lorsqu&#39;un étalonnage est nécessaire.</p><p>Vous pouvez définir l&#39;intervalle entre les étalonnages, le son à jouer, etc.</p><div class="admonition xdrip"><p class="admonition-title">Alertes de calibration</p></div><div class="admonition xdripitem"><p class="admonition-title">Alertes de calibration<img src="'+s+'" style="zoom:75%;"></p><p> Alerte lorsqu&#39;une calibration est demandée</p></div><div class="admonition xdripitem"><p class="admonition-title">Heures entre les calibrations</p><p> Combien d&#39;heures entre les demandes de calibration</p></div><div class="admonition xdripitem"><p class="admonition-title">Son de demande de calibration</p><p> Par défaut</p></div><div class="admonition xdripitem"><p class="admonition-title">Ignorer le mode silencieux<img src="'+r+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Même lors de la charge<img src="'+r+'" style="zoom:75%;"></p><p> Décocher la case pour ne pas demander de calibrations lorsque le téléphone est en charge</p></div><div class="admonition xdripitem"><p class="admonition-title">Répéter les alertes<img src="'+r+'" style="zoom:75%;"></p><p> Continuer d&#39;alerter si aucune calibration n&#39;est réalisée</p></div><div class="admonition xdripitem"><p class="admonition-title">Minutes entre les répétition d&#39;alertes</p><p> 20</p></div><h5 id="initial-alert" tabindex="-1">Alerte initiale <a class="header-anchor" href="#initial-alert" aria-label="Permalink to &quot;Alerte initiale {#initial-alert}&quot;">​</a></h5><p>L&#39;alerte de calibration initiale sert au démarrage d&#39;un capteur qui nécessite un étalonnage initial : elle se déclenche lorsque suffisamment de bonnes valeurs sont disponibles pour étalonner.</p><div class="admonition xdripitem"><p class="admonition-title">Alerte initiale<img src="'+t+'" style="zoom:75%;"></p><p> Émettre un son lorsque la calibration initiale est demandée</p></div><h3 id="missed-reading-alert" tabindex="-1">Alerte lecture manquée <a class="header-anchor" href="#missed-reading-alert" aria-label="Permalink to &quot;Alerte lecture manquée {#missed-reading-alert}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Alerte lecture manquée</p></div><p>Si vous comptez sur xDrip pour vous alerter des hypos et des hypers, il est essentiel de vous assurer qu&#39;il reçoit bien les valeurs de glycémie. Pour votre sécurité, si vous n&#39;avez pas d&#39;autre alarme, activez cette fonction.</p><p>La configuration est semblable à celle des <a href="#glucose-level-alerts-list">alertes de niveau de glycémie</a>. <strong>Le son de l&#39;alarme doit être défini dans Autres alertes</strong> (voir <a href="#alert-preferences">plus bas</a>). Pour la tester, mettez votre téléphone en mode avion jusqu&#39;à ce qu&#39;elle se déclenche.</p><div class="admonition xdrip"><p class="admonition-title">☰ Configurer les lectures manqués</p><p> <small>✅ Activer l&#39;alerte de lecture manquée</small><br>  <small>Alerte si aucune donnée reçue dans:</small><br>  <small><u> 30 </u> minutes</small><br>  <small>Sélectionner la période de l&#39;alerte:</small><br>  <small>✅ toute la journée</small></p><p> <small>Nombre de minutes avant de déclencher la même alerte après sa mise en veille:</small><br>  <small><u> 20 </u> minutes</small><br>  <small>☐ Relancer les alertes avant la durée de mise en veille</small><br>  <small>Délai de relance de l&#39;alerte:</small><br>  <small><u> 60 </u> secondes</small><br>  <small>☐ Ignorer le mode silencieux</small></p></div><h3 id="other-alerts" tabindex="-1">Autres alertes <a class="header-anchor" href="#other-alerts" aria-label="Permalink to &quot;Autres alertes {#other-alerts}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Autres alertes</p></div><h4 id="noisy-readings" tabindex="-1">Lectures de bruits <a class="header-anchor" href="#noisy-readings" aria-label="Permalink to &quot;Lectures de bruits {#noisy-readings}&quot;">​</a></h4><div class="admonition xdripitem"><p class="admonition-title"><small>LECTURES DE BRUITS</small></p></div><p>Si vous activez cette fonction et que votre capteur la prend en charge, vous pouvez configurer une alerte pour les valeurs bruitées.</p><div class="admonition xdripitem"><p class="admonition-title">Alertes de valeurs incorrectes (bruit)<img src="'+e+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Alerte après x minutes de valeurs de bruit</p><p> 90</p></div><div class="admonition xdripitem"><p class="admonition-title">Mise en veille d&#39;alerte</p><p> Nombre de minutes avant de déclencher la même alerte après sa mise en veille.</p></div><div class="admonition xdripitem"><p class="admonition-title">Relancer les alertes avant la durée de mise en veille<img src="'+e+'" style="zoom:75%;"></p><p> Relancer l&#39;alerte si non mise en veille plus tôt</p></div><div class="admonition xdripitem"><p class="admonition-title">Temps de relance de l&#39;alerte</p><p> Nombre de SECONDES à attendre avant de relancer la même alerte.</p></div><h4 id="falling-or-rising-bg" tabindex="-1">Chute ou hausse de la glycémie <a class="header-anchor" href="#falling-or-rising-bg" aria-label="Permalink to &quot;Chute ou hausse de la glycémie {#falling-or-rising-bg}&quot;">​</a></h4><div class="admonition xdripitem"><p class="admonition-title"><small>CHUTE/HAUSSE DE LA GLYCÉMIE</small></p></div><p>Vous pouvez aussi configurer des alertes pour les variations rapides de glycémie et définir la variation par minute qui les déclenche. Par exemple, 3 par minute correspond à 15 mg/dl (0,85 mmol/l) toutes les 5 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">Glycémie en chute rapide<img src="'+e+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">seuil de chute</p><p> 3 mg/dl/min (0.17 mmol/l/min)</p></div><div class="admonition xdripitem"><p class="admonition-title">Glycémie en augmentation rapide<img src="'+e+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">seuil d&#39;augmentation</p><p> 3 mg/dl/min (0.17 mmol/l/min)</p></div><h5 id="alert-preferences" tabindex="-1">Préférences d&#39;alerte <a class="header-anchor" href="#alert-preferences" aria-label="Permalink to &quot;Préférences d&#39;alerte {#alert-preferences}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title"><small>PRÉFÉRENCES D&#39;ALERTE (POUR CES ALERTES)</small></p></div><p>Les alertes ci-dessus, <strong>ainsi que Lectures manquées</strong>, utilisent le son et la vibration définis ci-dessous.<br> Depuis le <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9 sept. 2026</a>, xDrip les joue lui-même : les <a href="#notification-channels">canaux de notification</a> ne contrôlent plus le son ni la vibration. Les <a href="#alert-volume-profile">profils de volume d&#39;alerte</a> Vibreur uniquement et Silencieux s&#39;appliquent aussi à ces alertes. Lorsque le téléphone est en mode vibreur, seule la vibration est jouée ; en mode silencieux, rien n&#39;est joué sauf si Substituer le mode silencieux pour ces alertes est activé.</p><div class="warning custom-block"><p class="custom-block-title">Testez l&#39;alarme</p><p>C&#39;est une fonction importante pour dormir en sécurité. Réduisez la durée des lectures manquées et mettez votre téléphone en mode avion (sans Wi-Fi) pour forcer l&#39;alarme à sonner.</p></div><div class="admonition xdripitem"><p class="admonition-title">Son d&#39;alerte</p><p> Par défaut</p></div><p>Par défaut correspond au son propre à xDrip : l&#39;alarme xDrip pour les lectures manquées, un son de notification plus doux pour les autres alertes. Utilisez CHOISIR LE FICHIER pour choisir une sonnerie du téléphone ou votre propre fichier. Depuis le <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.25" target="_blank" rel="noreferrer">25 sept. 2026</a>, le son plus doux est aussi utilisé lorsque la sonnerie <em>Par défaut</em> du téléphone est sélectionnée, y compris sur les installations mises à jour depuis une version antérieure au 9 sept. 2026 qui n&#39;ont jamais modifié ce paramètre : les alertes de valeur incertaine, de hausse, de chute et similaires ne ressemblent plus à l&#39;alarme de glycémie.</p><div class="admonition xdripitem"><p class="admonition-title">Substituer le mode silencieux pour ces alertes<img src="'+a+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Vibrer en cas d&#39;alerte<img src="'+a+'" style="zoom:75%;"></p></div><h3 id="extra-alerts" tabindex="-1">Alertes supplémentaires <a class="header-anchor" href="#extra-alerts" aria-label="Permalink to &quot;Alertes supplémentaires {#extra-alerts}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Alertes supplémentaires (xDrip+)</p></div><h5 id="persistent-high-alert" tabindex="-1">Alerte Haute persistante <a class="header-anchor" href="#persistent-high-alert" aria-label="Permalink to &quot;Alerte Haute persistante {#persistent-high-alert}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Alerte Haute persistante</p></div><p>Au lieu d&#39;une alerte Haute qui se déclenche dès que la glycémie atteint la valeur de déclenchement, vous pouvez configurer une alerte Haute persistante qui ne se déclenche que si la glycémie reste au-dessus d&#39;une valeur définie pendant plus d&#39;une certaine durée. Vous pouvez utiliser la <a href="./settings.html#glucose-units">Valeur Haute</a> de xDrip ou une valeur de votre choix pour déclencher cette alerte.</p><div class="admonition xdripitem"><p class="admonition-title">Activer<img src="'+s+'" style="zoom:75%;"></p><p> Notifier si le seuil ci-dessus est plus long que la durée spécifiée ci-dessous</p></div><div class="admonition xdripitem"><p class="admonition-title">Seuil : Valeur Haute<img src="'+t+'" style="zoom:75%;"></p><p> Lorsque cette option est activée, la valeur Haute est le seuil.<br>  Lorsqu&#39;elle est désactivée, le seuil est la valeur spécifiée ci-dessous.</p></div><div class="admonition xdripitem"><p class="admonition-title">Seuil</p><p> 170 mg/dl</p></div><div class="admonition xdripitem"><p class="admonition-title">pendant plus de (minutes)</p><p> 60</p></div><div class="admonition xdripitem"><p class="admonition-title">Répétition maximum toutes les (minutes)</p><p> 20</p></div><div class="admonition xdripitem"><p class="admonition-title">Son d&#39;alerte</p><p> Choisissez le son utilisé pour l&#39;alarme.</p></div><div class="admonition xdripitem"><p class="admonition-title">Ignorer le mode silencieux<img src="'+e+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Vibrer en cas d&#39;alerte<img src="'+a+'" style="zoom:75%;"></p></div><h5 id="forecasted-low-alert" tabindex="-1">Alerte de prévisions d&#39;hypoglycémie <a class="header-anchor" href="#forecasted-low-alert" aria-label="Permalink to &quot;Alerte de prévisions d&#39;hypoglycémie {#forecasted-low-alert}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Alerte de prévisions d&#39;hypoglycémie</p></div><p>Vous pouvez définir une alarme sur une prévision d&#39;hypoglycémie. Cette fonction utilise l&#39;<strong>impulsion</strong> (extrapolation de la tendance actuelle de la glycémie) et <strong>pas</strong> les paramètres de <a href="./predictions.html">prédiction</a>. Le seuil de prévision (en minutes) est le délai dans lequel une hypoglycémie est prévue (celui qui s&#39;affiche habituellement en jaune sur l&#39;écran du graphique).</p><p>Les prévisions d&#39;hypoglycémie affichent un message sur l&#39;écran de xDrip. Pour qu&#39;une alarme sonne lorsqu&#39;une hypoglycémie est prévue, activez Déclencher alarme sur prévision Basse.</p><div class="admonition xdripitem"><p class="admonition-title">Prévisions Basses<img src="'+t+'" style="zoom:75%;"></p><p> Considérant la valeur actuelle et la tendance, calculer ce que seront les prochaines lectures si la tendance persiste (extrapolation). Cela ignore l&#39;insuline ou les glucides ingérés.</p></div><div class="admonition xdripitem"><p class="admonition-title">Déclencher alarme sur prévision Basse<img src="'+e+'" style="zoom:75%;"></p><p> Notifier lorsque les prédictions Basses atteignent le seuil</p></div><div class="admonition xdripitem"><p class="admonition-title">Seuil : Valeur basse<img src="'+t+'" style="zoom:75%;"></p><p> Lorsque cette option est activée, la valeur basse est le seuil.<br>  Lorsqu&#39;elle est désactivée, le seuil est la valeur spécifiée ci-dessous.</p></div><div class="admonition xdripitem"><p class="admonition-title">Seuil</p><p> 70 mg/dl</p></div><div class="admonition xdripitem"><p class="admonition-title">Seuil de prévisions d&#39;hypoglycémies [minutes]</p><p> 40</p></div><div class="admonition xdripitem"><p class="admonition-title">Son d&#39;alerte</p><p> Choisissez le son utilisé pour l&#39;alarme.</p></div><div class="admonition xdripitem"><p class="admonition-title">Ignorer le mode silencieux<img src="'+e+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Vibrer en cas d&#39;alerte<img src="'+a+'" style="zoom:75%;"></p></div><p>Dans l&#39;exemple ci-dessous, si vous réglez le Seuil de prévisions d&#39;hypoglycémies à 50 minutes, l&#39;alarme se déclenche. La ligne pointillée rouge est la tendance de glycémie prévue, extrapolée à partir des mesures précédentes.</p><img src="'+g+'" style="zoom:75%;"><h5 id="sensor-expiry-notifications" tabindex="-1">Notifications d&#39;expiration des capteurs <a class="header-anchor" href="#sensor-expiry-notifications" aria-label="Permalink to &quot;Notifications d&#39;expiration des capteurs {#sensor-expiry-notifications}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Notifications d&#39;expiration des capteurs</p><p> Notifier lorsque le capteur est proche de l&#39;expiration.</p></div><div class="admonition xdripitem"><p class="admonition-title">Activer<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Notifier lorsque le capteur est proche de l&#39;expiration.</p></div><p>Depuis le <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9 sept. 2026</a>, un abonné affiche la même notification lorsque l&#39;avertissement d&#39;expiration du téléphone principal lui parvient, à condition que ce paramètre soit aussi activé sur l&#39;abonné et que les traitements soient synchronisés depuis le téléphone principal. L&#39;avertissement s&#39;affiche une fois par avertissement du capteur, et il est ignoré s&#39;il arrive sur l&#39;abonné avec plus de 30 minutes de retard.</p><h5 id="follower-chime-new" tabindex="-1">Nouvelle sonnerie pour les abonnés <a class="header-anchor" href="#follower-chime-new" aria-label="Permalink to &quot;Nouvelle sonnerie pour les abonnés {#follower-chime-new}&quot;">​</a></h5><p>Après des lectures manquées, une notification sonne lorsque de nouvelles données arrivent après plus de 20 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">Nouvelle sonnerie pour les abonnés<img src="'+s+'" style="zoom:75%;"></p><p> Avertir si des données arrivent du maître si l&#39;intervalle est &gt; 20 mins.</p></div><h2 id="snooze-alert" tabindex="-1">Mise en veille Alertes <a class="header-anchor" href="#snooze-alert" aria-label="Permalink to &quot;Mise en veille Alertes {#snooze-alert}&quot;">​</a></h2><div class="admonition xdrip"><p class="admonition-title"><img src="'+u+'" style="zoom:75%;"></p><p> Mise en veille Alertes</p></div><p>S&#39;il n&#39;y a pas d&#39;alerte active, vous pouvez <strong>mettre en veille à l&#39;avance</strong> les alertes depuis ce menu pour qu&#39;elles ne se déclenchent pas pendant un certain temps.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+n+'" style="zoom:75%;">Mise en veille</p><div style="text-align:center;"> Aucune alerte active existe</div><div style="background-color:gray;color:white;text-align:center;">  Désactiver alertes Basses </div><div style="background-color:gray;color:white;text-align:center;">  Désactiver alertes Hautes </div><div style="background-color:gray;color:white;text-align:center;">  Désactiver toutes les alertes </div></div><p>Une durée de mise en veille par défaut vous est proposée. Faites défiler vers le haut ou le bas pour la modifier.</p><div class="admonition xdrip"><p class="admonition-title">Mise en veille par défaut</p><div style="background-color:darkgray;color:dimgray;text-align:center;">  50 minutes </div><div style="background-color:darkgray;color:black;text-align:center;">  60 minutes </div><div style="background-color:darkgray;color:dimgray;text-align:center;">  70 minutes </div></div><p>Lorsqu&#39;une alerte se déclenche, vous voyez la notification dans le volet déroulant de votre téléphone, et vous entendez éventuellement le son.</p><p>Vous pouvez mettre l&#39;alerte en veille en balayant la notification, ou la personnaliser davantage en appuyant dessus.</p><img src="'+b+'" style="zoom:75%;"><p>Vous pouvez ouvrir le menu de mise en veille en appuyant sur la notification ou depuis le menu principal de xDrip, Mise en veille Alertes.</p><p>Le menu de mise en veille affiche alors aussi l&#39;alerte active.<br> Appuyer sur Mise en veille la met en veille pour la durée sélectionnée.</p>',185)),l("div",L,[i[1]||(i[1]=l("p",{class:"admonition-title"},[l("img",{src:n,style:{zoom:"75%"}}),p("Mise en veille")],-1)),l("div",E,[c(d,null,{default:m(()=>[c(d,null,{default:m(()=>[...i[0]||(i[0]=[p("Mise en veille",-1)])]),_:1})]),_:1})]),i[2]||(i[2]=o('<div style="background-color:dimgray;color:white;text-align:center;">  <div style="background-color:black;color:dimgray;text-align:center;">  20 minutes </div><div style="background-color:black;color:darkgray;text-align:center;">  30 minutes </div><div style="background-color:black;color:dimgray;text-align:center;">  40 minutes </div></div><p>L&#39;alerte active nommée &quot;Night&quot; existe. Alerte se reproduira à 1:25:01 (0 minutes restantes)</p><div style="background-color:dimgray;color:white;text-align:center;">  Désactiver alertes Basses </div><div style="background-color:dimgray;color:white;text-align:center;">  Désactiver alertes Hautes </div><div style="background-color:dimgray;color:white;text-align:center;">  Désactiver toutes les alertes </div>',5))]),i[4]||(i[4]=o('<h5 id="all-alerts-currently-disabled" tabindex="-1">TOUTES LES ALERTES ACTUELLEMENT DÉSACTIVÉES <a class="header-anchor" href="#all-alerts-currently-disabled" aria-label="Permalink to &quot;TOUTES LES ALERTES ACTUELLEMENT DÉSACTIVÉES {#all-alerts-currently-disabled}&quot;">​</a></h5><p>Si vous mettez en veille à l&#39;avance (désactivez) toutes les alertes, ce message d&#39;avertissement s&#39;affiche.</p><img src="'+f+'" style="zoom:75%;"><p>Pour le faire disparaître, vous devez réactiver les alertes.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+n+'" style="zoom:75%;">Mise en veille</p><div style="text-align:center;"> Toutes les alertes désactivées jusqu&#39;à 15:09:12</div><div style="background-color:gray;color:white;text-align:center;">  Re-activer toutes les alertes </div></div><br><h2 id="visible-alert-notification" tabindex="-1">Notification d&#39;alerte visible <a class="header-anchor" href="#visible-alert-notification" aria-label="Permalink to &quot;Notification d&#39;alerte visible {#visible-alert-notification}&quot;">​</a></h2><p>Disponible à partir d&#39;Android 8.</p><p>Lorsqu&#39;une alerte se déclenche, elle apparaît dans le volet déroulant des notifications.</p><img src="'+x+'" style="zoom:75%;"><p>La balayer la met en veille, appuyer dessus ouvre un menu de préférences.<br> Distribuer en mode silencieux ne concerne que la notification Android elle-même. Depuis le <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9 sept. 2026</a>, le son et la vibration de l&#39;alerte sont joués par xDrip et suivent les paramètres d&#39;alerte de xDrip, et non le <a href="#notification-channels">canal de notification</a>.</p><img src="'+y+'" style="zoom:75%;"><p>Vous pouvez revenir à la distribution avec alerte depuis le même menu.</p><img src="'+q+'" style="zoom:75%;"><p>Paramètres vous mène aux réglages des notifications de votre téléphone.</p><img src="'+A+'" style="zoom:75%;"><p>Vous pouvez aussi désactiver complètement les <a href="#notification-channels">canaux de notification</a> de xDrip. Cela masque les notifications mais n&#39;arrête pas le son de l&#39;alerte.</p><img src="'+z+'" style="zoom:75%;"><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',19))])}const G=_(P,[["render",R]]);export{$ as __pageData,G as default};
